  ui_story_30330508_27_dialog_content = "<color=#e8d9bb>Hace unos 14 años, el continente se vio sumido en el caos por los Eclipsites invasores.</color>",
  ui_story_30330508_28_dialog_content = "<color=#e8d9bb>Entre sus objetivos, un gran grupo de Eclipsites atacó una ciudad llamada Ciudad de Varaki.</color>",
  ui_story_30330508_29_dialog_content = "<color=#e8d9bb>Pero los residentes lograron evacuar una noche antes de la llegada de los Eclipsites.</color>",
  ui_story_30330508_30_dialog_content = "<color=#e8d9bb>Fue True Order quien los evacuó.</color>",
  ui_story_30330508_31_dialog_content = "La invasión de Eclipsites fue muy inesperada, hubieron grandes pérdidas en todas partes.",
  ui_story_30330508_32_dialog_content = "Para la gente que vive en pueblitos de la frontera,",
  ui_story_30330508_33_dialog_content = "era imposible escapar de la incursión Eclipsite sin aviso previo.",
  ui_story_30330508_34_dialog_content = "¿Cómo lograron evacuar a todos en una noche?",
  ui_story_30330508_35_dialog_content = "Estamos felices de ayudar a los habitantes de la ciudad de Varaki.",
  ui_story_30330508_36_dialog_content = "Recuerdo que tocamos puerta por puerta, advirtiendo del peligro inminente.",
  ui_story_30330508_37_dialog_content = "Mostraron dudas, pero al final confiaron en nosotros y salieron de sus casas.",
  ui_story_30330508_38_dialog_content = "En cuanto a por qué, tal vez porque somos amables por naturaleza, por un lado presumiendo credibilidad y por otro eligiendo la confianza.",
  ui_story_30330508_39_dialog_content = "<color=#e8d9bb>Los esfuerzos publicitarios de True Order han aumentado en los últimos años.</color>",
  ui_story_30330508_40_dialog_content = "<color=#e8d9bb>Se centró principalmente en la difusión de la Verdad, sobre todo en pequeños discursos sin grandes asambleas.</color>",
  ui_story_30330508_41_dialog_content = "<color=#e8d9bb>Aunque hay miembros de Illumina, Umbraton, e incluso Lumopolis,</color>",
  ui_story_30330508_42_dialog_content = "<color=#e8d9bb>el objetivo se mantiene en pueblitos no regidos por facciones importantes.</color>",
  ui_story_30330508_43_dialog_content = "<color=#e8d9bb>Hecho sin comportamientos poco éticos también.</color>",
  ui_story_30330508_44_dialog_content = "<color=#e8d9bb>Pero según la investigación, hace una docena de años, algunos miembros menores se desviaron por desesperación...</color>",
  ui_story_30330508_45_dialog_content = "<color=#e8d9bb>Se involucraron en actividades radicales parecido a sacrificios.</color>",
  ui_story_30330508_46_dialog_content = "<color=#e8d9bb>True Order no tardó en denunciar el comportamiento como conducta personal y prohibió a otros miembros que lo imitasen.</color>",
  ui_story_30330508_47_dialog_content = "<color=#e8d9bb>Es comprobado que la Orden no realiza evaluaciones de admisión estrictas ni autenticación de identidad.</color>",
  ui_story_30330508_48_dialog_content = "<color=#e8d9bb>En general, el nivel de organización no es alto.</color>",
  ui_story_30330508_49_dialog_content = "<color=#e8d9bb>Ya sean lemas o supuestas doctrinas, es incomprensible.</color>",
  ui_story_30330508_50_dialog_content = "<color=#e8d9bb>Aparte de la mención incesante de la \"Verdad\", difícilmente se proporciona ninguna instrucción u orientación específica.</color>",
  ui_story_30330508_51_dialog_content = "¿Cuál es la Verdad?",
  ui_story_30330508_52_dialog_content = "No es necesario tratar de encontrar la Verdad, PlayerName. Puede estar justo delante de ti.",
  ui_story_30330508_53_dialog_content = "Incomprensible, ciertamente.",
  ui_story_30330508_54_dialog_content = "Profundizamos en el tema y encontramos un entendimiento inconsistente sobre la Verdad entre los miembros.",
  ui_story_30330508_55_dialog_content = "Unos dijeron que el conocimiento es La Verdad, otros que las artes...",
  ui_story_30330508_56_dialog_content = "La Verdad es diferente para cada uno.",
  ui_story_30330508_57_dialog_content = "Sus respuestas son similares a las del Sr. Faust: abstractas y ambiguas.",
  ui_story_30330508_58_dialog_content = "Honestamente, yo tampoco lo entiendo.",
  ui_story_30330508_59_dialog_content = "<color=#e8d9bb>Hasta la fecha, no se han detectado actividades sospechosas.</color>",
  ui_story_30330508_60_dialog_content = "<color=#e8d9bb>Actualmente están clasificados como \"No una amenaza\"</color>",
  ui_story_30330508_61_dialog_content = "<color=#e8d9bb>Por otro lado, seguimos investigando las \"semillas\" mencionadas en el informe.</color>",
  ui_story_30330508_62_dialog_content = "<color=#e8d9bb>Por favor, infórmanos de cualquier dato que pueda recoger en el futuro.</color>",
  ui_story_30330508_63_dialog_content = "Este informe no menciona el plan final de True Order.",
  ui_story_30330508_64_dialog_content = "¿Parece que estás absolutamente seguro de ocultar el verdadero objetivo?",
  ui_story_30330508_65_dialog_content = "Como La Verdad, los objetivos pueden conocerse a través del ensayo y error persistente.",
  ui_story_30330508_66_dialog_content = "La última vez no tuvimos la oportunidad por una emergencia.",
  ui_story_30330508_67_dialog_content = "Pero esta vez, has llegado al Colossus por ti mismo. ¿No temes que esta vez te obliguemos a revelar secretos?",
  ui_story_30330508_68_dialog_content = "Eres bienvenido a intentarlo.",
  ui_story_30330508_69_dialog_content = "Ahora, hablemos. Veremos si me sacas secretos...",
  ui_story_30330508_70_dialog_content = "¿O persuadirte que te unas a nosotros primero?",
  ui_story_30330508_71_dialog_content = "Lo hablamos cuando me encontré con el Sr. Faust hace poco.",
  ui_story_30330508_72_dialog_content = "Escucharle hablar de la Verdad me dio bastante dolor de cabeza, PlayerName.",
  ui_story_30330508_73_dialog_content = "¡Vaya, no te fíes fácilmente de los desconocidos que encuentras en el camino!",
  ui_story_30330508_74_dialog_content = "Todo está bien. No pienso en el Sr. Faust como un extraño.",
  ui_story_30330508_75_dialog_content = "Estoy muy feliz de tener un intercambio contigo.",
  ui_story_30330508_76_dialog_content = "Entonces, adelante, habla. Quiero saber qué haces, ¡incluso si corres el riesgo de convertirte!",
  ui_story_30330508_77_dialog_content = "Tu coraje es muy admirable.",
  ui_story_30330508_78_dialog_content = "Pero, se me acabó el tiempo. Por favor, permíteme partir.",
  ui_story_30330508_79_dialog_content = "¿En serio? ¿Crees que puedes ir y venir a tu antojo?",
  ui_story_30330508_80_dialog_content = "Lo siento, pero Soroz ha despegado. Es difícil que te vayas ahora.",
  ui_story_30330508_81_dialog_content = "Ya es difícil para nosotros mantener el vuelo a baja altura, PlayerName.",
  ui_story_30330508_82_dialog_content = "Es suficiente.",
  ui_story_30330508_83_dialog_content = "Vaya, no esperaba que estuvieras tan decidido.",
  ui_story_30330508_84_dialog_content = "Una vez vi cómo operan los bandidos, no creo que esto sea excesivo, teniendo en cuenta la circunstancia.",
  ui_story_30330508_85_dialog_content = "No somos completamente irracionales. Hay té negro y café en la cafetería.",
  ui_story_30330508_86_dialog_content = "¿Te quedas a charlar un poco más?",
  ui_story_30330508_87_dialog_content = "Olvidas que Aviduz también se iba en ese momento.",
  ui_story_30330508_88_dialog_content = "¿En ese momento? Ah, sí, ¿cómo saliste? No me digas que puedes volar como Curie...",
  ui_story_30330508_89_dialog_content = "No, salté.",
  ui_story_30330508_90_dialog_content = "¿Saltaste?",
  ui_story_30330508_91_dialog_content = "Sí. Pedí a una joven que manipulaba espinas y al hombre que controlaba la sangre que me salvaran.",
  ui_story_30330508_92_dialog_content = "Aunque me dijeron que era mucho esfuerzo localizar mi lugar exacto de aterrizaje.",
  ui_story_30330508_93_dialog_content = "¡Cuidado, PlayerName!",
  ui_story_30330508_94_dialog_content = "¿Qué acaba de abrir la escotilla?",
  ui_story_30330508_95_dialog_content = "¿De dónde salió todo el líquido rojo? ¡Qué asco!",
  ui_story_30330508_96_dialog_content = "¡Y las espinas verdes! ¡¿Alguien los controla?!",
  ui_story_30330508_97_dialog_content = "Perdón, mi viaje llegó. No puedo hacerles esperar.",
  ui_story_30330508_98_dialog_content = "¿Hay algo que quieras decir antes de que nos separemos?",
  ui_story_30330508_99_option_content = "Tengo una última pregunta...",
  ui_story_30330508_100_dialog_content = "¿Eres amigo o enemigo?",
  ui_story_30330508_101_dialog_content = "La Verdad te lo dirá al final.",
  ui_story_30330508_102_option_content = "Ah, antes que me olvide...",
  ui_story_30330508_103_dialog_content = "Gracias por salvarme la última vez, y disculpas por cualquier grosería mostrada hoy.",
  ui_story_30330508_104_dialog_content = "No te preocupes, hacemos lo que tenemos que hacer.",
  ui_story_30330508_105_dialog_content = "Que la Verdad los bendiga.",
  ui_story_30330508_106_dialog_content = "Pues bien, hasta la próxima, PlayerName.",
  ui_story_30330508_107_dialog_content = "Hasta la próxima.",
  ui_story_30330509_1_dialog_content = "Vice, dijiste que había una cosa más que tenías que hacer... ¿Qué era?",
  ui_story_30330509_2_dialog_content = "Quiero ver a la oficial Vivian antes de irnos.",
  ui_story_30330509_3_dialog_content = "Es una extraña aquí, y aún no se ha recuperado del todo.",
  ui_story_30330509_4_dialog_content = "Probablemente le vendría bien ver una cara familiar ahora mismo...",
  ui_story_30330509_5_dialog_content = "Además, creo que sería mejor si le informamos de nuestro próximo curso de acción...",
  ui_story_30330509_6_dialog_content = "¿Deberíamos llevarle a Vivian un regalo para que se mejore?",
  ui_story_30330509_7_dialog_content = "Bueno, tengo mi cartera conmigo. Podemos comprar algo por el camino cuando pasemos por el mercado de la Baja Lumopolis.",
  ui_story_30330509_8_dialog_content = "¡Espérenme! ¡Raphaela también quiere venir!",
  ui_story_30330509_9_dialog_content = "Raphaela, ¿no estabas con Carleen hace un momento? Oye, ¿dónde está Gronru?",
  ui_story_30330509_10_dialog_content = "Gronru recibió un pedido urgente y se dirigió a Illumina. Acabo de despedirla.",
  ui_story_30330509_11_dialog_content = "Carleen también volvió a los Guardianes para entregar sus deberes...",
  ui_story_30330509_12_dialog_content = "Bueno, todos parecen muy ocupados hoy.",
  ui_story_30330509_13_dialog_content = "¡Raphaela también está muy ocupada!",
  ui_story_30330509_14_dialog_content = "Pues bien, Raphaela, ¡muchas gracias por sacar tiempo de tu apretada agenda para acompañarnos!",
  ui_story_30330509_15_dialog_content = "Erm. Cierto. ¡Muchas gracias!",
  ui_story_30330509_16_dialog_content = "Jeejee, de nada.",
  ui_story_30330509_17_dialog_content = "¡Bien entonces, vamos!",
  ui_story_30330509_18_dialog_content = "<color=#e8d9bb> Mercado de Baja Lumopolis</color>",
  ui_story_30330509_19_dialog_content = "El mercado está... ¡alborotado!",
  ui_story_30330509_20_dialog_content = "Este lugar acaba de pasar por una gran catástrofe, pero ha conseguido recuperarse tan rápidamente.",
  ui_story_30330509_21_dialog_content = "Aunque todo el mundo dice que la Baja Lumopolis es sucia y desordenada, y un lugar apto sólo para civiles y los nobles más insignificantes...",
  ui_story_30330509_22_dialog_content = "A Raphaela le gusta aquí. Es encantador y acogedor.",
  ui_story_30330509_23_dialog_content = "Comandante Raphaela, ¡al fin te encontré!",
  ui_story_30330509_24_dialog_content = "¿Eh? ¿Qué es?",
  ui_story_30330509_25_dialog_content = "Carleen... La capitana de los guardianes va a ceder hoy sus funciones, y hay algunos asuntos que requieren tu atención.",
  ui_story_30330509_26_dialog_content = "¿Carleen? Ella ya me explicó todo... Entonces, ¿qué pasa...?",
  ui_story_30330509_27_dialog_content = "No conozco los detalles. Sólo me ha pedido que te busque lo antes posible.",
  ui_story_30330509_28_dialog_content = "¡Muy bien, lo has hecho bien! ¡Estaré ahí!",
  ui_story_30330509_29_dialog_content = "¡Guardia, por favor escolte a estos dos invitados por mí!",
  ui_story_30330509_30_dialog_content = "¡Sí, Caballero Comandante!",
  ui_story_30330509_31_dialog_content = "PlayerName, Vice, discúlpenme. ¡Es otro día ocupado para Raphaela!",
  ui_story_30330509_32_dialog_content = "¡Volveré a buscarles cuando hayan terminado!",
  ui_story_30330509_33_dialog_content = "Se ha ido... Raphaela corre tan rápido.",
  ui_story_30330509_34_dialog_content = "PlayerName, vamos a comprar algo para la oficial Vivian aquí.",
  ui_story_30330509_35_dialog_content = "¿Cuál crees que es mejor?",
  ui_story_30330509_36_dialog_content = "Bueno...",
  ui_story_30330509_37_option_content = "Compra flores",
  ui_story_30330509_38_dialog_content = "Quizás estas coloridas flores la animen un poco.",
  ui_story_30330509_39_dialog_content = "Cuando Vivian las vea, seguro que le arrancan una sonrisa.",
  ui_story_30330509_40_option_content = "Compra fruta",
  ui_story_30330509_41_dialog_content = "Unas frutas dulces, deliciosas y nutritivas deberían servir.",
  ui_story_30330509_42_dialog_content = "Le darán a Vivian un buen empujón de energía.",
  ui_story_30330509_43_dialog_content = "PlayerName, no sabía que fueras tan experto en regalos de bienestar.",
  ui_story_30330509_44_dialog_content = "... Sólo creo que, si yo estuviera enfermo, me gustaría esto.",
  ui_story_30330509_45_dialog_content = "¡Entonces compremos todo!",
  ui_story_30330509_46_dialog_content = "Erm.",
  ui_story_30330509_47_dialog_content = "¿Qué pasa, Vice?",
  ui_story_30330509_48_dialog_content = "Mi cartera... <color=#FFB400>¡Se ha ido!</color>",
  ui_story_30330509_49_dialog_content = "¿Seguro que la tenías contigo?",
  ui_story_30330509_50_dialog_content = "¡Me aseguré específicamente de tenerla antes de salir! Mi cartera estaba definitivamente aquí...",
  ui_story_30330509_51_dialog_content = "¿Puedes decirme cómo es?",
  ui_story_30330509_52_dialog_content = "Cabe en la palma, y es blanca por todas partes... ¡con mi propio emblema especial!",
  ui_story_30330509_53_dialog_content = "Tal vez se te cayó en el camino hacia aquí... ¡Dividámonos y busquémosla!",
  ui_story_30330509_54_dialog_content = "Busqué en toda la ruta y no encontré nada. ¿Y tú?",
  ui_story_30330509_55_dialog_content = "Nada...",
  ui_story_30330509_56_dialog_content = "Yo tampoco pude encontrarla.",
  ui_story_30330509_57_dialog_content = "... ¡Preguntaré por ahí!",
  ui_story_30330509_58_dialog_content = "Discúlpeme, señor. ¿Ha visto una <color=#FFB400>cartera blanca</color> por aquí?",
  ui_story_30330509_59_dialog_content = "¿Una cartera blanca?",
  ui_story_30330509_60_dialog_content = "Sí, ¿la ha visto? ¡Tiene un emblema!",
  ui_story_30330509_61_dialog_content = "Acabo de ver a un Caballero Lumo con una bonita cartera blanca en la mano.",
  ui_story_30330509_62_dialog_content = "Realmente no parecía el tipo de cosa que se encontraría en Lumopolis, así que llamó bastante la atención.",
  ui_story_30330509_63_dialog_content = "Un Caballero Lumo...",
  ui_story_30330509_64_dialog_content = "¿Sabes dónde está ese soldado ahora?",
  ui_story_30330509_65_dialog_content = "Lo vi caminando hacia Zona residencial",
  ui_story_30330509_66_dialog_content = "¡Gracias, señor!",
  ui_story_30330509_67_dialog_content = "Noche Blanca en lo alto... Que encuentre su cartera perdida.",
  ui_story_30330509_68_dialog_content = "Un Caballero Lumo lo tomó... ¿Es realmente posible...?",
  ui_story_30330509_69_dialog_content = "Guardia, ¿puede recordar algo?",
  ui_story_30330509_70_dialog_content = "También vi un Caballero Lumo en mi camino hacia aquí.",
  ui_story_30330509_71_dialog_content = "Lo reconocí. Fue transferido de los Caballeros Lumo a los Guardianes.",
  ui_story_30330509_72_dialog_content = "Y antes de unirse a los Caballeros Lumo, era sólo un civil.",
  ui_story_30330509_73_dialog_content = "En ese momento, recuerdo que pensé que era extraño lo nervioso que parecía, pero no pregunté porque estaba ocupado con mis deberes...",
  ui_story_30330509_74_dialog_content = "¡Ahora es obvio que te robó la cartera y huyó con mala conciencia!",
  ui_story_30330509_75_dialog_content = "¿Por qué sospechas tanto de él?",
  ui_story_30330509_76_dialog_content = "Bueno, he oído que está pasando por una mala racha recientemente...",
  ui_story_30330509_77_dialog_content = "¿Puede un Caballero de Lumo estar tan desesperado por dinero?",
  ui_story_30330509_78_dialog_content = "Un noble no lo haría, pero para un plebeyo, es difícil de decir.",
  ui_story_30330509_X78_dialog_content = "¿Ah?",
  ui_story_30330509_79_dialog_content = "La codicia insaciable está grabada en sus huesos. Sólo se convierten en soldados por el salario y el estatus.",
  ui_story_30330509_80_dialog_content = "Sin honor y fe en su corazón, ¿cómo podría una persona así tener la fuerza de voluntad para hacer lo correcto?",
  ui_story_30330509_81_dialog_content = "Robar el dinero de alguien... ¡Es un crimen imperdonable!",
  ui_story_30330509_82_dialog_content = "Todo este asunto parece demasiado peculiar. Creo que puede haber un malentendido en alguna parte...",
  ui_story_30330509_83_dialog_content = "Tienes razón, PlayerName. ¡Primero encontremos al soldado!",
  ui_story_30330509_84_dialog_content = "<color=#e8d9bb>Templo de Lumopolis</color>",
  ui_story_30330509_85_dialog_content = "Aquí está. Alguien dijo que lo vio entrar allí.",
  ui_story_30330509_86_dialog_content = "Vice... ¿Qué es este lugar?",
  ui_story_30330509_87_dialog_content = "Este es un templo dedicado a la deidad de Lumopolis, el <color=#FFB400>Dios de la Luz</color>.",
  ui_story_30330509_88_dialog_content = "El gran Dios de la Luz, en mi búsqueda de este criminal, por favor, perdóname por cualquier transgresión involuntaria que pueda cometer. Noche Blanca en lo alto...",
  ui_story_30330509_89_dialog_content = "Muy bien, entremos.",
  ui_story_30330509_90_dialog_content = "Dios de la Luz, que creaste todas las cosas, que tienes misericordia de todos los seres vivos...",
  ui_story_30330509_91_dialog_content = "Por favor, perdóname, y los malos pensamientos en mi mente...",
  ui_story_30330509_92_dialog_content = "Aunque fue sólo un momento de debilidad, quise tomar esa cartera para mí.",
  ui_story_30330509_93_dialog_content = "Por favor, perdóname. Encontraré al dueño de inmediato...",
  ui_story_30330509_94_dialog_content = "Se misericordioso, y castígame como creas conveniente... pero por favor perdona a mi hermana.",
  ui_story_30330509_95_dialog_content = "Noche Blanca en lo alto...",
  ui_story_30330509_96_dialog_content = "¡Lo encontré! ¡Está ahí mismo!",
  ui_story_30330509_97_dialog_content = "Ahí, en su mano... ¡Realmente es mi cartera!",
  ui_story_30330509_98_dialog_content = "¡Inútil gruñón! ¿Te atreves a manchar este templo, sólo para mostrarle al Dios de la Luz lo que hiciste?",
  ui_story_30330509_99_dialog_content = "¡...!",
  ui_story_30330509_100_dialog_content = "¡Te castigaré... por los Caballeros de Lumo!",
  ui_story_30330509_101_dialog_content = "¡Espera un minuto! Aclaremos todo esto primero...",
  ui_story_30330509_102_dialog_content = "¿De dónde sacaste esa cartera en tu mano?",
  ui_story_30330509_103_dialog_content = "La encontré en las calles de la Baja Lumopolis.",
  ui_story_30330509_104_dialog_content = "¿Así que la recogiste?",
  ui_story_30330509_105_dialog_content = "Pero por el color y el emblema que lleva puedo ver que en realidad es mi cartera.",
  ui_story_30330509_106_dialog_content = "... ¿Es tu cartera? Señorita, ¿puede decirme qué contiene?",
  ui_story_30330509_107_dialog_content = "Por supuesto. En primer lugar, hay un montón de Nightium adentro...",
  ui_story_30330509_108_dialog_content = "Y, lo más importante, hay una papeleta de racionamiento de la Federación Illumina para el té de la tarde.",
  ui_story_30330509_109_dialog_content = "¡Alabado sea el Dios de la Luz! ¡Realmente es tuya!",
  ui_story_30330509_110_dialog_content = "Aquí tiene, señorita. Por favor, tómela.",
  ui_story_30330509_112_dialog_content = "Todo sigue aquí. ¡Gracias, soldado!",
  ui_story_30330509_113_dialog_content = "¿Por qué corrió hasta aquí en lugar de tratar de encontrar al dueño inmediatamente?",
  ui_story_30330509_114_dialog_content = "Yo...",
  ui_story_30330509_115_dialog_content = "¿Mmm? PlayerName, ¿Vice? ¿Qué hacen aquí?",
  ui_story_30330509_116_dialog_content = "Y tú, soldado, ¿por qué no pude encontrarte hace un momento?",
  ui_story_30330509_117_dialog_content = "Caballero Comandante, ¿estabas... Buscándome?",
  ui_story_30330509_119_dialog_content = "¡Comandante Raphaela, llega justo a tiempo!",
  ui_story_30330509_120_dialog_content = "Esta joven perdió su cartera en la Baja Lumopolis, y finalmente ha reaparecido en las manos de este soldado.",
  ui_story_30330509_121_dialog_content = "Aunque afirmó que simplemente la había encontrado en la calle, no pudo explicar por qué no trató de encontrar a la dueña de inmediato.",
  ui_story_30330509_122_dialog_content = "Además, últimamente he oído rumores de que necesita dinero desesperadamente... Así que sospecho que sus intenciones eran deshonrosas.",
  ui_story_30330509_123_dialog_content = "Hmm... ¿Es eso así?",
  ui_story_30330509_124_dialog_content = "Yo... Realmente necesito dinero. Eso es cierto...",
  ui_story_30330509_125_dialog_content = "Porque mi hermana... Está muy enferma... pero no tengo suficiente dinero para darle el tratamiento que necesita...",
  ui_story_30330509_127_dialog_content = "Entonces, ¿recurriste a robar?",
  ui_story_30330509_128_dialog_content = "¡Noche Blanca en lo alto! ¡Juro por el Dios de la Luz que no he robado nada!",
  ui_story_30330509_129_dialog_content = "Mirando a mi pobre hermana, pensé en pedir dinero prestado.",
  ui_story_30330509_130_dialog_content = "Pero tan pronto como salí, encontré esa cartera...",
  ui_story_30330509_131_dialog_content = "Al principio, pensé que era un regalo del Dios de la Luz... y que iba a coger el dinero y buscar un médico.",
  ui_story_30330509_132_dialog_content = "Pero cuando llegué al centro médico, me caí al suelo... Entonces me senté en el suelo, y mi mente se aclaró de repente...",
  ui_story_30330509_133_dialog_content = "El objeto que tenía en la mano pertenecía claramente a otra persona...",
